import React, { useState, useEffect, useCallback, useMemo, useRef, memo } from 'react';
import { useNavigate } from 'react-router-dom';
import { FixedSizeList } from 'react-window';
import { useTheme } from '@mui/material/styles';
import { Link } from '@mui/material';
import {
  Box,
  Button,
  Typography,
  CircularProgress,
  Autocomplete,
  TextField,
} from '@mui/material';
import { Download as DownloadIcon } from '@mui/icons-material';
import { downloadText } from '../utils/downloadFile';
import { getVersions, getVersionDiff } from '../utils/api';
import { formatDateTime } from '../utils/dateFormatter';
import ListboxComponent from '../utils/VirtualListbox';

const ROW_HEIGHT = 20;
const DIFF_LIST_HEIGHT_VH = 55;

const LINE_COLORS = {
  added:     { bg: { light: '#e6ffed', dark: 'rgba(46, 160, 67, 0.15)' },   text: 'success.main', prefix: '+ ' },
  removed:   { bg: { light: '#ffeef0', dark: 'rgba(248, 81, 73, 0.15)' },   text: 'error.main',   prefix: '− ' },
  unchanged: { bg: null,                                                       text: 'text.primary', prefix: '  ' },
};

// Одна колонка diff (левая или правая)
const DiffCell = memo(({ lineNum, content, prefix, showContent, bgColor, textColor, lineNumWidth, borderRight }) => (
  <Box sx={{ display: 'flex', minHeight: 20, minWidth: 0, ...(borderRight && { borderRight: 1, borderColor: 'divider' }) }}>
    <Box sx={{
      width: lineNumWidth, minWidth: lineNumWidth,
      px: 1, textAlign: 'right', color: 'text.secondary',
      bgcolor: showContent && bgColor ? bgColor : 'rgba(0,0,0,0.02)',
      userSelect: 'none', borderRight: 1, borderColor: 'divider', flexShrink: 0,
      fontFamily: 'monospace', fontSize: '0.75rem', lineHeight: '20px',
    }}>
      {showContent ? lineNum : ''}
    </Box>
    <Box sx={{
      flex: 1, minWidth: 0, px: 1,
      overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
      color: textColor, fontFamily: 'monospace', fontSize: '0.75rem', lineHeight: '20px',
    }}>
      {showContent ? prefix + (content || '') : ''}
    </Box>
  </Box>
));

const DiffRow = memo(({ line, lineNumWidth }) => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';
  const colors = LINE_COLORS[line.type] || LINE_COLORS.unchanged;
  const bgColor = colors.bg ? (isDark ? colors.bg.dark : colors.bg.light) : 'background.paper';

  const showLeft = line.type === 'removed' || line.type === 'unchanged';
  const showRight = line.type === 'added' || line.type === 'unchanged';

  return (
    <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', bgcolor: bgColor }}>
      <DiffCell
        lineNum={line.leftLineNum}
        content={line.content}
        prefix={showLeft ? colors.prefix : '  '}
        showContent={showLeft}
        bgColor={bgColor}
        textColor={colors.text}
        lineNumWidth={lineNumWidth}
        borderRight
      />
      <DiffCell
        lineNum={line.rightLineNum}
        content={line.content}
        prefix={showRight ? colors.prefix : '  '}
        showContent={showRight}
        bgColor={bgColor}
        textColor={colors.text}
        lineNumWidth={lineNumWidth}
      />
    </Box>
  );
});

const buildUnifiedDiff = (lines, leftName, rightName) => {
  const SPLIT_THRESHOLD = 7;
  const CONTEXT = 3;
  const header = [`--- ${leftName}`, `+++ ${rightName}`];

  const hunks = [];
  let currentHunk = [];
  let unchangedRun = 0;

  for (const line of lines) {
    if (line.type === 'unchanged') {
      unchangedRun++;
      currentHunk.push(line);
      if (unchangedRun >= SPLIT_THRESHOLD) {
        const trimmed = currentHunk.slice(0, currentHunk.length - unchangedRun + CONTEXT);
        if (trimmed.some(l => l.type !== 'unchanged')) {
          hunks.push(trimmed);
        }
        currentHunk = currentHunk.slice(currentHunk.length - CONTEXT);
        unchangedRun = CONTEXT;
      }
    } else {
      unchangedRun = 0;
      currentHunk.push(line);
    }
  }

  if (currentHunk.some(l => l.type !== 'unchanged')) {
    let lastChanged = currentHunk.length - 1;
    while (lastChanged >= 0 && currentHunk[lastChanged].type === 'unchanged') lastChanged--;
    hunks.push(currentHunk.slice(0, Math.min(currentHunk.length, lastChanged + 1 + CONTEXT)));
  }

  const output = [...header];
  for (const hunkLines of hunks) {
    const leftLines = hunkLines.filter(l => l.type !== 'added');
    const rightLines = hunkLines.filter(l => l.type !== 'removed');
    const leftStart = leftLines.find(l => l.leftLineNum)?.leftLineNum || 1;
    const rightStart = rightLines.find(l => l.rightLineNum)?.rightLineNum || 1;
    output.push(`@@ -${leftStart},${leftLines.length} +${rightStart},${rightLines.length} @@`);
    for (const line of hunkLines) {
      const c = line.content || '';
      if (line.type === 'added') output.push(`+${c}`);
      else if (line.type === 'removed') output.push(`-${c}`);
      else output.push(` ${c}`);
    }
  }

  return output.join('\n') + '\n';
};

const DiffStats = ({ stats, totalLines, onDownload }) => (
  <Box
    sx={{
      display: 'flex',
      alignItems: 'center',
      gap: 1.5,
      px: 2,
      py: 1,
      bgcolor: 'action.hover',
      borderBottom: 1,
      borderColor: 'divider',
      fontFamily: 'monospace',
      fontSize: '0.8125rem',
    }}
  >
    <Typography sx={{ color: 'success.main', fontWeight: 600 }}>
      +{stats.added}
    </Typography>
    <Typography sx={{ color: 'error.main', fontWeight: 600 }}>
      -{stats.removed}
    </Typography>
    <Typography sx={{ color: 'text.secondary', fontSize: '0.75rem', ml: 'auto' }}>
      Всего строк: {totalLines}
    </Typography>
    {onDownload && (
      <Button size="small" startIcon={<DownloadIcon />} onClick={onDownload} variant="outlined" sx={{ ml: 1, fontFamily: 'inherit' }}>
        Скачать .patch
      </Button>
    )}
  </Box>
);

const ChangesTab = ({
  embedded = false,
  initialDiffData = null,
  deviceName = null,
  version1Date = null,
  version2Date = null,
  leftTitle = null,
  rightTitle = null,
  leftDeviceId = null,
  rightDeviceId = null,
  rightDeviceName = null,
  leftVersionId = null,
  rightVersionId = null,
  onViewVersion = null,
  downloadFilename = null,
}) => {
  const theme = useTheme();
  const navigate = useNavigate();
  const listContainerRef = useRef(null);
  const [listSize, setListSize] = useState({ width: 0, height: 400 });
  const [versions, setVersions] = useState([]);
  const [loading, setLoading] = useState(!embedded);
  const [error, setError] = useState(null);
  const [selectedVersion1, setSelectedVersion1] = useState(null);
  const [selectedVersion2, setSelectedVersion2] = useState(null);
  const [diffData, setDiffData] = useState(initialDiffData);
  const [diffLoading, setDiffLoading] = useState(false);
  const [diffError, setDiffError] = useState(null);

  useEffect(() => {
    const el = listContainerRef.current;
    if (!el) return;
    const updateSize = () => {
      setListSize({ width: el.clientWidth, height: el.clientHeight });
    };
    updateSize();
    const ro = new ResizeObserver(updateSize);
    ro.observe(el);
    return () => ro.disconnect();
  }, [diffData]);

  const loadVersions = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await getVersions();
      setVersions(data);
    } catch (err) {
      const errorMessage = err.response
        ? `Ошибка ${err.response.status}: ${err.response.data?.error || err.message}`
        : err.message || 'Не удалось подключиться к серверу. Проверьте, что API сервер запущен.';
      setError('Ошибка при загрузке данных: ' + errorMessage);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (embedded) {
      setLoading(false);
      if (initialDiffData) {
        setDiffData(initialDiffData);
      }
    } else {
      loadVersions();
    }
  }, [loadVersions, embedded, initialDiffData]);

  const handleCompare = useCallback(async () => {
    if (!selectedVersion1 || !selectedVersion2) {
      setDiffError('Выберите обе версии для сравнения');
      return;
    }

    if (selectedVersion1 === selectedVersion2) {
      setDiffError('Выберите разные версии для сравнения');
      return;
    }

    try {
      setDiffLoading(true);
      setDiffError(null);
      const diff = await getVersionDiff(selectedVersion1, selectedVersion2);
      setDiffData(diff);
    } catch (err) {
      const errorMessage = err.response
        ? `Ошибка ${err.response.status}: ${err.response.data?.error || err.message}`
        : err.message || 'Не удалось получить данные сравнения';
      setDiffError('Ошибка при получении данных сравнения: ' + errorMessage);
      setDiffData(null);
    } finally {
      setDiffLoading(false);
    }
  }, [selectedVersion1, selectedVersion2]);

  const getVersionInfo = (versionId) => {
    return versions.find(v => v.id === parseInt(versionId));
  };

  const processedDiff = useMemo(() => {
    if (!diffData || !diffData.lines || diffData.lines.length === 0) {
      return null;
    }

    const lines = diffData.lines;

    const stats = { added: 0, removed: 0 };
    lines.forEach(line => {
      if (line.type === 'added') stats.added++;
      if (line.type === 'removed') stats.removed++;
    });

    if (stats.added === 0 && stats.removed === 0) {
      return { identical: true };
    }

    const processedLines = [];
    let leftLineNum = 1;
    let rightLineNum = 1;

    lines.forEach((line) => {
      processedLines.push({
        ...line,
        leftLineNum: line.left_num !== undefined ? line.left_num : (line.type === 'removed' || line.type === 'unchanged' ? leftLineNum++ : null),
        rightLineNum: line.right_num !== undefined ? line.right_num : (line.type === 'added' || line.type === 'unchanged' ? rightLineNum++ : null),
      });
    });

    const maxLineNum = Math.max(
      ...processedLines.map(l => l.leftLineNum || 0),
      ...processedLines.map(l => l.rightLineNum || 0),
    );
    const lineNumWidth = Math.max(40, String(maxLineNum).length * 9 + 16);

    return {
      identical: false,
      stats,
      lines: processedLines,
      totalLines: lines.length,
      lineNumWidth,
    };
  }, [diffData]);

  const handleDownloadDiff = useCallback(() => {
    if (!processedDiff || processedDiff.identical) return;

    const leftName = leftTitle
      || (deviceName ? `${deviceName}${version1Date ? ` (${version1Date})` : ''}` : `version-${diffData?.left_version_id}`);
    const rightName = rightTitle
      || ((rightDeviceName || deviceName) ? `${rightDeviceName || deviceName}${version2Date ? ` (${version2Date})` : ''}` : `version-${diffData?.right_version_id}`);

    const content = buildUnifiedDiff(processedDiff.lines, leftName, rightName);

    const safe = (s) => String(s || '').replace(/[\\/:*?"<>|]/g, '_').replace(/\s+/g, '-').substring(0, 40);
    const filename = downloadFilename || `diff-${safe(leftName)}-vs-${safe(rightName)}.patch`;

    downloadText(content, filename);
  }, [processedDiff, leftTitle, rightTitle, deviceName, rightDeviceName, version1Date, version2Date, diffData, downloadFilename]);

  if (loading) {
    return (
      <Box sx={{ p: 2, textAlign: 'center' }}>
        <Typography>Загрузка версий...</Typography>
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ p: 2 }}>
        <Typography color="error">{error}</Typography>
        <Button onClick={loadVersions} sx={{ mt: 1 }} variant="outlined">
          Повторить
        </Button>
      </Box>
    );
  }

  const version1Info = selectedVersion1 ? getVersionInfo(selectedVersion1) : null;
  const version2Info = selectedVersion2 ? getVersionInfo(selectedVersion2) : null;

  return (
    <Box
      sx={{
        bgcolor: 'background.paper',
        borderRadius: 2,
        boxShadow: 1,
        p: 3,
      }}
    >
      {!embedded && (
        <>
          <Box sx={{ mb: 3, textAlign: 'center' }}>
            <Typography variant="h5" sx={{ color: 'text.primary', mb: 1 }}>
              Сравнение версий конфигураций
            </Typography>
          </Box>

            <Box
              sx={{
                display: 'grid',
                gridTemplateColumns: { xs: '1fr', md: '1fr 1fr' },
                gap: 2.5,
                mb: 2.5,
              }}
            >
              <Autocomplete
                ListboxComponent={ListboxComponent}
                options={versions}
                value={versions.find(v => v.id === selectedVersion1) || null}
                onChange={(_, newValue) => setSelectedVersion1(newValue?.id || null)}
                getOptionLabel={(option) => `${option.device_hostname} - ${formatDateTime(option.created_at)}`}
                isOptionEqualToValue={(option, value) => option.id === value.id}
                renderInput={(params) => (
                  <TextField {...params} label="Версия 1 (левая)" size="small" />
                )}
                disableClearable
              />
              {version1Info && (
                <Typography variant="body2" sx={{ color: 'text.secondary', mt: 1, fontSize: '0.75rem' }}>
                  {version1Info.device_hostname} | Создано: {formatDateTime(version1Info.created_at)}
                </Typography>
              )}

              <Autocomplete
                ListboxComponent={ListboxComponent}
                options={versions}
                value={versions.find(v => v.id === selectedVersion2) || null}
                onChange={(_, newValue) => setSelectedVersion2(newValue?.id || null)}
                getOptionLabel={(option) => `${option.device_hostname} - ${formatDateTime(option.created_at)}`}
                isOptionEqualToValue={(option, value) => option.id === value.id}
                renderInput={(params) => (
                  <TextField {...params} label="Версия 2 (правая)" size="small" />
                )}
                disableClearable
              />
              {version2Info && (
                <Typography variant="body2" sx={{ color: 'text.secondary', mt: 1, fontSize: '0.75rem' }}>
                  {version2Info.device_hostname} | Создано: {formatDateTime(version2Info.created_at)}
                </Typography>
              )}
            </Box>

          <Box sx={{ display: 'flex', justifyContent: 'center', my: 2.5 }}>
            <Button
              variant="contained"
              onClick={handleCompare}
              disabled={!selectedVersion1 || !selectedVersion2 || diffLoading}
              sx={{
                px: 3,
                py: 1.5,
                bgcolor: 'text.primary',
                '&:hover': { bgcolor: 'text.secondary' },
                '&:disabled': { bgcolor: 'action.disabledBackground' },
              }}
            >
              {diffLoading ? 'Сравнение...' : 'Сравнить версии'}
            </Button>
          </Box>
        </>
      )}

      {diffError && (
        <Box sx={{ mt: 2.5 }}>
          <Typography color="error">{diffError}</Typography>
        </Box>
      )}

      {diffData && processedDiff && (
        <Box
          sx={{
            mt: 3.75,
            border: 1,
            borderColor: 'divider',
            borderRadius: 1.5,
            overflow: 'hidden',
          }}
        >
          {processedDiff.identical ? (
            <Box
              sx={{
                p: 5,
                textAlign: 'center',
                color: 'text.secondary',
                bgcolor: 'action.hover',
              }}
            >
              Версии идентичны — изменений нет
            </Box>
          ) : (
            <>
              <DiffStats stats={processedDiff.stats} totalLines={processedDiff.totalLines} onDownload={handleDownloadDiff} />

              <Box
                sx={{
                  display: 'grid',
                  gridTemplateColumns: { xs: '1fr', md: '1fr 1fr' },
                  bgcolor: 'action.hover',
                  borderBottom: 1,
                  borderColor: 'divider',
                }}
              >
                <Box sx={{ display: 'flex', minWidth: 0 }}>
                  <Box
                    sx={{
                      width: processedDiff.lineNumWidth,
                      minWidth: processedDiff.lineNumWidth,
                      borderRight: 1,
                      borderColor: 'divider',
                      bgcolor: 'rgba(0,0,0,0.02)',
                    }}
                  />
                  <Box sx={{ p: 1, fontSize: '0.875rem', fontWeight: 600, color: 'text.secondary', minWidth: 0 }}>
                    {leftTitle ? (
                      <Link
                        component="button"
                        onClick={() => onViewVersion?.(leftVersionId)}
                        sx={{ color: 'inherit', textDecoration: 'none', '&:hover': { textDecoration: 'underline' } }}
                      >
                        {leftTitle}
                      </Link>
                    ) : version1Info ? (
                      <Link
                        component="button"
                        onClick={() => navigate(`/devices/${version1Info.id}`)}
                        sx={{ color: 'inherit', textDecoration: 'none', '&:hover': { textDecoration: 'underline' } }}
                      >
                        {version1Info.device_hostname}
                      </Link>
                    ) : leftDeviceId && deviceName ? (
                      <Link
                        component="button"
                        onClick={() => navigate(`/devices/${leftDeviceId}`)}
                        sx={{ color: 'inherit', textDecoration: 'none', '&:hover': { textDecoration: 'underline' } }}
                      >
                        {deviceName}
                      </Link>
                    ) : (
                      deviceName || `Версия ${diffData.left_version_id}`
                    )}
                    {version1Date && ` (${version1Date})`}
                  </Box>
                </Box>
                <Box sx={{ display: 'flex', minWidth: 0, borderLeft: { md: 1 }, borderColor: 'divider' }}>
                  <Box
                    sx={{
                      width: processedDiff.lineNumWidth,
                      minWidth: processedDiff.lineNumWidth,
                      borderRight: 1,
                      borderColor: 'divider',
                      bgcolor: 'rgba(0,0,0,0.02)',
                    }}
                  />
                  <Box sx={{ p: 1, fontSize: '0.875rem', fontWeight: 600, color: 'text.secondary', minWidth: 0 }}>
                    {rightTitle ? (
                      <Link
                        component="button"
                        onClick={() => onViewVersion?.(rightVersionId)}
                        sx={{ color: 'inherit', textDecoration: 'none', '&:hover': { textDecoration: 'underline' } }}
                      >
                        {rightTitle}
                      </Link>
                    ) : version2Info ? (
                      <Link
                        component="button"
                        onClick={() => navigate(`/devices/${version2Info.id}`)}
                        sx={{ color: 'inherit', textDecoration: 'none', '&:hover': { textDecoration: 'underline' } }}
                      >
                        {version2Info.device_hostname}
                      </Link>
                    ) : rightDeviceId && (rightDeviceName || deviceName) ? (
                      <Link
                        component="button"
                        onClick={() => navigate(`/devices/${rightDeviceId}`)}
                        sx={{ color: 'inherit', textDecoration: 'none', '&:hover': { textDecoration: 'underline' } }}
                      >
                        {rightDeviceName || deviceName}
                      </Link>
                    ) : (
                      deviceName || `Версия ${diffData.right_version_id}`
                    )}
                    {version2Date && ` (${version2Date})`}
                  </Box>
                </Box>
              </Box>

              <Box
                ref={listContainerRef}
                sx={{
                  fontFamily: 'monospace',
                  fontSize: '0.75rem',
                  lineHeight: '20px',
                  height: `max(${ROW_HEIGHT}px, min(${DIFF_LIST_HEIGHT_VH}vh, ${processedDiff.lines.length * ROW_HEIGHT}px))`,
                }}
              >
                {listSize.width > 0 && listSize.height > 0 && (
                  <FixedSizeList
                    height={listSize.height}
                    width={listSize.width}
                    itemCount={processedDiff.lines.length}
                    itemSize={ROW_HEIGHT}
                    overscanCount={10}
                  >
                    {({ index, style }) => (
                      <div style={style}>
                        <DiffRow
                          line={processedDiff.lines[index]}
                          lineNumWidth={processedDiff.lineNumWidth}
                        />
                      </div>
                    )}
                  </FixedSizeList>
                )}
              </Box>
            </>
          )}
        </Box>
      )}
    </Box>
  );
};

export default ChangesTab;